const group = new THREE.Group();
const count = 5;
const spacing = width / count;
const lWidth = spacing * 0.8;
const lDepth = depth;
const bHeight = height * 0.4;
const cThickness = height * 0.2;

const woodMat = new THREE.MeshStandardMaterial({color: 0x8b5a2b, roughness: 0.8});
const clothMat = new THREE.MeshStandardMaterial({color: 0xf0f0f0, roughness: 0.9});

for(let i=0; i<count; i++) {
    const x = -width/2 + spacing/2 + i*spacing;

    const baseGeo = new THREE.BoxGeometry(lWidth, bHeight, lDepth);
    const base = new THREE.Mesh(baseGeo, woodMat);
    base.position.set(x, -height/2 + bHeight/2, 0);
    group.add(base);

    const seatDepth = lDepth * 0.6;
    const seatGeo = new THREE.BoxGeometry(lWidth*0.9, cThickness, seatDepth);
    const seat = new THREE.Mesh(seatGeo, clothMat);
    seat.position.set(x, -height/2 + bHeight + cThickness/2, -lDepth/2 + seatDepth/2);
    group.add(seat);

    const backHeight = (height - bHeight) / Math.cos(Math.PI/6);
    const backGeo = new THREE.BoxGeometry(lWidth*0.9, backHeight, cThickness);
    const back = new THREE.Mesh(backGeo, clothMat);
    back.position.set(x, -height/2 + bHeight + (height - bHeight)/2, seat.position.z + seatDepth/2 + (backHeight/2)*Math.sin(Math.PI/6));
    back.rotation.x = Math.PI / 6;
    group.add(back);
}
return group;

